import pandas as pd

df = pd.read_csv('/app/dataset/hospital_compensation_registry.csv')

# Build dictionary representation of the graph
nodes = {}
successors = {}
predecessors = {}

for idx, row in df.iterrows():
    pid = row['patient_id']
    contact = row['emergency_contact_patient_id']

    nodes[pid] = {
        'first_name': row['first_name'],
        'second_name': row['second_name'],
        'full_name': row['full_name'],
        'compensation_reason': row['compensation_reason'],
        'direct_payment': row['direct_payment_usd'],
        'has_claim': pd.notnull(row['compensation_reason'])
    }

    if pid not in successors:
        successors[pid] = []
    successors[pid].append(contact)

    if contact not in predecessors:
        predecessors[contact] = []
    predecessors[contact].append(pid)

suspect_claimants = ['PAT_033', 'PAT_265', 'PAT_006']

print("--- Outgoing and Incoming emergency contacts for the claimants ---")
for node in suspect_claimants:
    if node in nodes:
        print(f"\nClaimant: {node} ({nodes[node]['full_name']}) - Reason: {nodes[node]['compensation_reason']} - Payment: {nodes[node]['direct_payment']}")
        # Outgoing (their emergency contact)
        succs = successors.get(node, [])
        print(f"  Lists as emergency contact: {succs}")
        for s in succs:
            if s in nodes:
                print(f"    -> {s} ({nodes[s]['full_name']}), has_claim={nodes[s]['has_claim']}, reason={nodes[s]['compensation_reason']}")
            else:
                print(f"    -> {s} (Not in registry)")
        # Incoming (who lists them as emergency contact)
        preds = predecessors.get(node, [])
        print(f"  Listed as emergency contact by: {preds}")
        for p in preds:
            if p in nodes:
                print(f"    <- {p} ({nodes[p]['full_name']}), has_claim={nodes[p]['has_claim']}, reason={nodes[p]['compensation_reason']}")
            else:
                print(f"    <- {p} (Not in registry)")

