import pandas as pd

df = pd.read_csv('/app/dataset/hospital_compensation_registry.csv')

contact_map = dict(zip(df['patient_id'], df['emergency_contact_patient_id']))
name_map = dict(zip(df['patient_id'], df['full_name']))
claim_map = dict(zip(df['patient_id'], df['compensation_reason']))

def trace_path(start_pid):
    path = []
    curr = start_pid
    visited = set()
    while curr in contact_map and curr not in visited:
        visited.add(curr)
        path.append(curr)
        curr = contact_map[curr]
    if curr in visited:
        path.append(f"{curr} (CYCLE)")
    else:
        path.append(f"{curr} (Not in registry)")
    return path

